//! 🧪️ Canonical export addresses retain source frames and independent stable-layer/RFC6902 observations.
use super::*;
use semio_framework_value::retirement::controlled::ControlledRetirement;
fn grant(d:RetirementDemand)->RetainedCloneGrant{RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:d.copy_bytes,maximum_capacity_bytes:d.capacity_bytes,maximum_release_bytes:d.release_bytes,maximum_depth:d.depth}}
fn close(state:FramePlanState){let mut owner=ControlledRetirement::new(state).unwrap_or_else(|_|panic!("controlled frame planner"));for _ in 0..100000{if owner.terminal_is_empty(){return;}let d=owner.next_demand(4096).unwrap();owner.step(grant(d)).unwrap();}panic!("frame planner close stalled");}
#[test]fn neutral_frame_plan_matches_independent_layer_and_patch_oracle(){let corpus:serde_json::Value=serde_json::from_str(include_str!("🧫️fixtures/🔣️.json")).unwrap();for vector in corpus["cases"].as_array().unwrap(){let doc:LayoutSnapshot=semio_framework_pack_json::from_json_str(&vector["document"].to_string(),semio_framework_pack_json::JsonMemberPolicy::Reject).unwrap();let targets=if doc.pages.len()==1{vec![None,Some(0)]}else{vec![None,Some(0),Some(doc.pages.len()-1)]};for _ in [1,7,4096]{for &target in &targets{let mut state=FramePlanState::new(target);for _ in 0..1000000{if state.ready(){break;}let d=state.demand(&doc).unwrap();let g=grant(d);if d.capacity_bytes>0{assert!(d.depth>=3);assert!(!state.prepare(&doc,RetainedCloneGrant{maximum_capacity_bytes:d.capacity_bytes-1,..g}).unwrap());assert_eq!(state.last_receipt().retained_capacity_bytes,0);}if d.copy_bytes>0{assert!(!state.prepare(&doc,RetainedCloneGrant{maximum_copy_bytes:d.copy_bytes-1,..g}).unwrap());assert_eq!(state.last_receipt().copied_bytes,0);}if d.depth>1{assert!(!state.prepare(&doc,RetainedCloneGrant{maximum_depth:d.depth-1,..g}).unwrap());assert_eq!(state.last_receipt().retained_capacity_bytes,0);assert_eq!(state.last_receipt().copied_bytes,0);}state.prepare(&doc,g).unwrap();let p=state.last_receipt();assert!(p.retained_capacity_bytes<=d.capacity_bytes);assert!(p.copied_bytes<=d.copy_bytes);}assert!(state.ready());let mut actual=Vec::new();for page in 0..doc.pages.len(){if target.is_some_and(|target|target!=page){continue;}for _ in 0..100000{match state.next(page).unwrap(){FramePlanTurn::Pending=>{},FramePlanTurn::Complete=>break,FramePlanTurn::Frame(address)=>{let original=match address.parent_index{Some(parent)=>&doc.parent_pages[parent].frames[address.frame_index],None=>&doc.pages[page].frames[address.frame_index]};let frame=address.frame(&doc).unwrap();assert!(std::ptr::eq(frame,original));let bounds=address.bounds(&doc).unwrap();actual.push(serde_json::json!({"address":{"pageIndex":address.page_index,"parentIndex":address.parent_index,"frameIndex":address.frame_index,"overrideIndex":address.override_index,"linkIndex":address.link_index},"id":frame.id(),"bounds":{"x":bounds.x,"y":bounds.y,"w":bounds.width,"h":bounds.height,"rotation":bounds.rotation},"visible":address.visible(&doc).unwrap()}));}}}}let expected:Vec<_>=vector["expected"].as_array().unwrap().iter().filter(|row|target.is_none_or(|page|row["address"]["pageIndex"].as_u64()==Some(page as u64))).cloned().collect();assert_eq!(actual,expected);assert!(state.demand(&doc.clone()).is_err());close(state);}}for cut in [0,1,20,1000]{let mut state=FramePlanState::new(None);for _ in 0..cut{if state.ready(){break;}let d=state.demand(&doc).unwrap();state.prepare(&doc,grant(d)).unwrap();}state.cancel();assert!(state.prepare(&doc,grant(RetirementDemand{depth:1,..Default::default()})).is_err());close(state);}}}

#[test]fn wide_long_identifier_frame_plan_borrows_large_text_payload(){let corpus:serde_json::Value=serde_json::from_str(include_str!("🧫️fixtures/🔣️.json")).unwrap();let mut doc:LayoutSnapshot=semio_framework_pack_json::from_json_str(&corpus["cases"][0]["document"].to_string(),semio_framework_pack_json::JsonMemberPolicy::Reject).unwrap();let wide=&corpus["wide"];let count=wide["frames"].as_u64().unwrap()as usize;let layers=wide["layers"].as_u64().unwrap()as usize;let prefix="🌍".repeat(wide["identifierScalars"].as_u64().unwrap()as usize);doc.parent_pages.clear();doc.pages.truncate(1);let story=doc.stories[0].id.clone();let page=&mut doc.pages[0];page.parent_page_id=None;page.overrides.clear();let layer=page.layers[0].clone();page.layers=(0..layers).map(|at|{let mut layer=layer.clone();layer.id=format!("{prefix}{at}");layer.object_ids.clear();layer}).collect();page.layer_ids=page.layers.iter().map(|layer|layer.id.clone()).collect();let original=page.frames[0].clone();page.frames=(0..count).map(|at|Frame::Rect{id:format!("wide-{at}"),layer_id:page.layers[at%layers].id.clone(),bounds:original.bounds().clone(),visible:None,locked:None,fill:None,stroke:None}).collect();let first=page.frames[0].clone();page.frames[0]=Frame::Text{id:first.id().into(),layer_id:first.layer_id().into(),bounds:first.bounds().clone(),visible:None,locked:None,story_id:story,thread_next:None,columns:1,inset:semio_s_artifact_layout_layout_model::LayoutRect{x:0.0,y:0.0,width:10.0,height:10.0},wrap_mode:"x".repeat(wide["wrapModeBytes"].as_u64().unwrap()as usize)};for at in 0..count{page.layers[at%layers].object_ids.push(format!("wide-{at}"));}let mut state=FramePlanState::new(Some(0));for _ in 0..1000000{if state.ready(){break;}let d=state.demand(&doc).unwrap();state.prepare(&doc,grant(d)).unwrap();}assert!(state.ready());let mut actual=Vec::new();for _ in 0..count+1{match state.next(0).unwrap(){FramePlanTurn::Frame(address)=>{assert!(std::ptr::eq(address.frame(&doc).unwrap(),&doc.pages[0].frames[address.frame_index]));actual.push(address.frame_index);},FramePlanTurn::Complete=>break,FramePlanTurn::Pending=>{}}}let expected:Vec<usize>=wide["expectedFrameIndices"].as_array().unwrap().iter().map(|n|n.as_u64().unwrap()as usize).collect();assert_eq!(actual,expected);close(state);}
